Method.Source:
/// <summary>
/// PaffH 30.04.24
/// </summary>
/// <param name = "_contract">IHostContract</param>
/// <returns>NDXAzureRelayTransferPALabel</returns>
public NDXAzureRelayTransferPALabel initializeAzureRelay(IHostContract _contract)
{
    keyVaultGetSecretRelay = new KeyVaultGetSecretRelayPALabelSave();
    keyVaultGetSecretRelay.KeyVaultValue = NDXKeyVaultHelper::GetKeyVaultSecretValueFromD365FO(NDXProdIdentControlPanelParameters::find().KeyVaultSecretNameConnectionStringAzureRelayD365FO, "@NDX:NDXMissingEntryKeyVaultSecretNameRelayPALabel");
    if (keyVaultGetSecretRelay.KeyVaultValue == null)
    {
        error("@NDX:NDXErrorInitADOConnectionStringAzureRelay");
    }
    else
    {
        azureRelaySender = new Niedax.AzureRelayHelper.PALabel.AzureRelaySenderPALabel(keyVaultGetSecretRelay);
        this.initMaintainRelayContract(_contract);
    }
    return this;
}

/// <summary>
/// PaffH 30.04.24
/// </summary>
/// <param name = "_contract">IHostContract</param>
public void initMaintainRelayContract(IHostContract _contract)
{
    NDXHostURL hostURL = NDXEnvironmentInformation::construct().parmHostUrl();
    _contract.Host = NDXEnvironmentHostURLMapping::find(hostURL).Host;
    _contract.GeneratedDateTime = NDXHelperCommon::utcNowUser();
}
